public boolean compatibleWithBlock(TFMLogicBlock _block)
{
    return classIdGet(_block) == classNum(MwmsLogicBlockMoveInvent);
}

public void modifyRegistrationCollectors(TFMRegistrationCollectors _collectors)
{
    //Add to dimensions for all fields
    TFMRegistrationCollectors   collectors  = TFMInventDimHelper::enabledInventDimCollectors('',false, false, false);
    MapEnumerator               mEnum       = collectors.collectorMap().getEnumerator();
    TFMRegistrationCollector    col;
    super(_collectors);
    while (mEnum.moveNext())
    {
        col = mEnum.currentValue();
        col.parmName('to'+col.parmName());
        col.parmHeader(col.parmHeader() + '('+"To"+')');
    }
    _collectors.mergeCollectors(collectors);
}
